.form-field.has-error input {
  border-color: var(--color-error-border);
  background-color: var(--color-error-bg);
}

.form-field.has-error input:focus {
  outline-color: #fca5a5;
}

.error-message {
  font-size: 0.8125rem;
  color: var(--color-error);
