.status-message {
  border-radius: var(--radius);
  padding: 0.75rem 1rem;
  font-size: 0.9375rem;
  font-weight: 500;
  margin-top: 1.25rem;
  display: none;
  align-items: flex-start;
  gap: 0.5rem;
}

.status-message.success {
  background-color: var(--color-success-bg);
  border: 1px solid var(--color-success-border);
  color: var(--color-success);
  display: flex;
