+  background: var(--color-primary);
+  color: #fff;
+  padding: 0.5rem 1rem;
+  border-radius: var(--radius);
+  font-weight: 600;
+  text-decoration: none;
+  z-index: 100;
+  transition: top 0.1s;
+}
+.skip-link:focus {
+  top: 1rem;
+  outline: 3px solid var(--color-primary-focus-ring);
+  outline-offset: 2px;
+}
